  // integrate the heading properly so the path is a smooth arc rather than a rotated ray
  let p = [...tip];
  const out = [p];
  for (let i = 1; i <= n; i++) {
    const s = (i - 0.5) / n, a = dir + bend * deg * s * s;
    p = [p[0] + Math.cos(a) * reach / n, p[1] + Math.sin(a) * reach / n];
    out.push(p);
  }
  return { pts: out, hw };
}

