// Fissure from inside the spark, out through its tip and past the stone edge.
// The heading drifts as it travels (bend), so the four fissures read as a slow pinwheel.
function fissure(tip, centre, { bend, reach, w0, w1, start = 0.55, n = 48 }) {
  const dir = Math.atan2(tip[1] - centre[1], tip[0] - centre[0]);
  const from = [centre[0] + (tip[0] - centre[0]) * start, centre[1] + (tip[1] - centre[1]) * start];
  const pts = [from, [...tip]], hw = [w0 / 2, w0 / 2];
  let p = [...tip];
  for (let i = 1; i <= n; i++) {
    const s = (i - 0.5) / n, a = dir + bend * deg * s * s;
    p = [p[0] + Math.cos(a) * reach / n, p[1] + Math.sin(a) * reach / n];
    pts.push(p);
    hw.push((w0 + (w1 - w0) * Math.pow(i / n, 0.8)) / 2);
  }
  return { pts, hw };
}

